CREATE OR REPLACE FUNCTION coderdojo.maintain_member(p_actor uuid, p_action text, p_id uuid, p_fields jsonb DEFAULT '{}'::jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  current_member coderdojo.members%rowtype;
  actor_member coderdojo.members%rowtype;
  result_id uuid;
  target_parent_id uuid;
  target_category_id uuid;
  account_value coderdojo.members%rowtype;
begin
  -- A single lock gives deterministic duplicate checks across simultaneous maintenance requests.
  perform pg_advisory_xact_lock(731101);
  select * into actor_member from coderdojo.members where id = p_actor and not deleted and is_mentor for share;
  if not found then raise exception 'Mentor access required' using errcode = '42501'; end if;
  if p_action = 'create' then
    account_value := jsonb_populate_record(null::coderdojo.members, p_fields);
  else
    select * into current_member from coderdojo.members where id = p_id and not deleted for update;
    if not found then raise exception 'Member not found' using errcode = 'P0002'; end if;
    account_value := jsonb_populate_record(current_member, p_fields);
  end if;

  if p_action in ('create', 'account', 'goals', 'profile') then
    if p_action <> 'create' and not (to_jsonb(current_member) @> p_expected) then
      raise exception 'Member changed; reload before saving' using errcode = 'P0001';
    end if;
    if p_action in ('create', 'account') then
      if not (account_value.is_ninja or account_value.is_parent or account_value.is_mentor) then
        raise exception 'Select at least one role' using errcode = '22023';
      end if;
      if p_actor = p_id and not account_value.is_mentor then
        raise exception 'Cannot remove your own mentor role' using errcode = '22023';
      end if;
      if account_value.team_id is not null and not exists (select 1 from coderdojo.teams where id = account_value.team_id and not deleted) then
        raise exception 'Team not found' using errcode = '22023';
      end if;
      if exists (select 1 from coderdojo.members where not deleted and id <> p_id and
        ((account_value.login is not null and lower(trim(login)) = lower(trim(account_value.login))) or
         (account_value.fingerprint_id is not null and fingerprint_id = account_value.fingerprint_id) or
         (account_value.nfc_tag is not null and nfc_tag = account_value.nfc_tag))) then
        raise exception 'Login, fingerprint or NFC identifier already used' using errcode = '23505';
      end if;
      if p_action = 'account' and
         ((not account_value.is_parent and exists (select 1 from coderdojo.member_parents where parent_id = p_id)) or
          (not account_value.is_ninja and exists (select 1 from coderdojo.member_parents where member_id = p_id)) or
          (not account_value.is_mentor and exists (select 1 from coderdojo.member_badge_categories where member_id = p_id))) then
        raise exception 'Remove related children, parents or skills before removing their role' using errcode = '22023';
      end if;
    end if;
    if p_action = 'create' then
      insert into coderdojo.members (id,name_first,name_last,email,phone,github_login,scratch_name,xbox_gamertag,
        birth_year,fingerprint_id,nfc_tag,login,team_id,registered_current_term,is_ninja,is_parent,is_mentor,garda_vetted,password_hash)
      values (p_id,account_value.name_first,account_value.name_last,account_value.email,account_value.phone,
        account_value.github_login,account_value.scratch_name,account_value.xbox_gamertag,account_value.birth_year,
        account_value.fingerprint_id,account_value.nfc_tag,account_value.login,account_value.team_id,
        account_value.registered_current_term,account_value.is_ninja,account_value.is_parent,account_value.is_mentor,
        account_value.garda_vetted,account_value.password_hash) returning * into current_member;
    elsif p_action = 'account' then
      update coderdojo.members set birth_year=account_value.birth_year,fingerprint_id=account_value.fingerprint_id,
        nfc_tag=account_value.nfc_tag,login=account_value.login,team_id=account_value.team_id,
        registered_current_term=account_value.registered_current_term,is_ninja=account_value.is_ninja,
        is_parent=account_value.is_parent,is_mentor=account_value.is_mentor,garda_vetted=account_value.garda_vetted
      where id=p_id returning * into current_member;
    elsif p_action = 'goals' then
      if not current_member.is_ninja then raise exception 'Coder required' using errcode='22023'; end if;
      update coderdojo.members set goal_short_term=account_value.goal_short_term,goal_long_term=account_value.goal_long_term
      where id=p_id returning * into current_member;
    else
      update coderdojo.members set name_first=account_value.name_first,name_last=account_value.name_last,
        email=account_value.email,phone=account_value.phone,github_login=account_value.github_login,
        scratch_name=account_value.scratch_name,xbox_gamertag=account_value.xbox_gamertag
      where id=p_id returning * into current_member;
    end if;
    return to_jsonb(current_member) - 'password_hash';
  elsif p_action = 'password' then
    update coderdojo.members set password_hash=p_fields->>'password_hash' where id=p_id;
    return null;
  elsif p_action in ('link', 'unlink') then
    target_parent_id := (p_fields->>'parent_id')::uuid;
    perform 1 from coderdojo.members where id=target_parent_id and not deleted and is_parent for share;
    if not found or not current_member.is_ninja or p_id=target_parent_id then
      raise exception 'Active coder and parent required' using errcode='22023';
    end if;
    if p_action='unlink' then
      delete from coderdojo.member_parents where member_id=p_id and member_parents.parent_id=target_parent_id;
      return null;
    end if;
    select id into result_id from coderdojo.member_parents where member_id=p_id and member_parents.parent_id=target_parent_id limit 1;
    if result_id is null then
      insert into coderdojo.member_parents(member_id,parent_id) values(p_id,target_parent_id) returning id into result_id;
    end if;
    return jsonb_build_object('id',result_id,'memberId',p_id,'parentId',target_parent_id);
  elsif p_action in ('skill', 'unskill') then
    target_category_id := (p_fields->>'badge_category_id')::uuid;
    if not current_member.is_mentor then raise exception 'Mentor required' using errcode='22023'; end if;
    if p_action='unskill' then
      delete from coderdojo.member_badge_categories where member_id=p_id and badge_category_id=target_category_id;
      return null;
    end if;
    if not exists(select 1 from coderdojo.badge_categories where id=target_category_id and not deleted) then
      raise exception 'Category not found' using errcode='22023';
    end if;
    select id into result_id from coderdojo.member_badge_categories where member_id=p_id and badge_category_id=target_category_id limit 1;
    if result_id is null then
      insert into coderdojo.member_badge_categories(member_id,badge_category_id) values(p_id,target_category_id) returning id into result_id;
    end if;
    return jsonb_build_object('id',result_id,'memberId',p_id,'badgeCategoryId',target_category_id);
  end if;
  raise exception 'Unsupported maintenance action' using errcode='22023';
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.maintain_definition(p_actor uuid, p_kind text, p_action text, p_id uuid, p_fields jsonb DEFAULT '{}'::jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 current_value jsonb;
 name_value text;
 description_value text;
 hex_value text;
 sort_value integer;
 category_value uuid;
begin
 perform pg_advisory_xact_lock(731101);
 perform 1 from coderdojo.members where id=p_actor and not deleted and is_mentor for share;
 if not found then raise exception 'Mentor access required' using errcode='42501'; end if;
 if p_kind not in ('belt','badge','category') or p_action not in ('create','update','delete') then raise exception 'Invalid definition action' using errcode='22023'; end if;
 if p_action <> 'create' then
  if p_kind='belt' then
   select jsonb_build_object('name',coalesce(color,''),'description',description,'hexCode',hex_code,'sortOrder',sort_order,'categoryId',null) into current_value from coderdojo.belts where id=p_id and not deleted for update;
  elsif p_kind='badge' then
   select jsonb_build_object('name',coalesce(achievement,''),'description',description,'hexCode',null,'sortOrder',null,'categoryId',badge_category_id) into current_value from coderdojo.badges where id=p_id and not deleted for update;
  else
   select jsonb_build_object('name',coalesce(category_name,''),'description',category_description,'hexCode',null,'sortOrder',null,'categoryId',null) into current_value from coderdojo.badge_categories where id=p_id and not deleted for update;
  end if;
  if current_value is null then raise exception 'Definition not found' using errcode='P0002'; end if;
  if p_expected is distinct from current_value then raise exception 'Definition changed elsewhere. Reload before saving.' using errcode='P0001'; end if;
 end if;
 if p_action='delete' then
  if p_kind='category' and (exists(select 1 from coderdojo.badges where badge_category_id=p_id and not deleted) or exists(select 1 from coderdojo.member_badge_categories where badge_category_id=p_id)) then raise exception 'Reassign badges and remove mentor skills before deleting this category.' using errcode='P0001'; end if;
  if p_kind='belt' then update coderdojo.belts set deleted=true where id=p_id;
  elsif p_kind='badge' then update coderdojo.badges set deleted=true where id=p_id;
  else update coderdojo.badge_categories set deleted=true where id=p_id; end if;
  return current_value || jsonb_build_object('id',p_id,'kind',p_kind,'deleted',true);
 end if;
 if p_fields is null or (p_fields - array['name','description','hexCode','sortOrder','categoryId']) <> '{}'::jsonb then raise exception 'Invalid definition fields' using errcode='22023'; end if;
 name_value := btrim(p_fields->>'name'); description_value := p_fields->>'description'; hex_value := p_fields->>'hexCode'; sort_value := (p_fields->>'sortOrder')::integer; category_value := (p_fields->>'categoryId')::uuid;
 if name_value is null or length(name_value) not between 1 and 150 or length(coalesce(description_value,''))>4000 or (hex_value is not null and hex_value !~ '^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$') or (p_kind='belt' and (sort_value is null or sort_value not between 0 and 10000)) or (p_kind<>'belt' and (sort_value is not null or hex_value is not null)) or (p_kind<>'badge' and category_value is not null) then raise exception 'Invalid definition fields' using errcode='22023'; end if;
 if p_kind='badge' and not exists(select 1 from coderdojo.badge_categories where id=category_value and not deleted) then raise exception 'Select an active category.' using errcode='22023'; end if;
 if (p_kind='belt' and exists(select 1 from coderdojo.belts where not deleted and id<>p_id and lower(btrim(color))=lower(name_value))) or (p_kind='category' and exists(select 1 from coderdojo.badge_categories where not deleted and id<>p_id and lower(btrim(category_name))=lower(name_value))) or (p_kind='badge' and exists(select 1 from coderdojo.badges where not deleted and id<>p_id and badge_category_id=category_value and lower(btrim(achievement))=lower(name_value))) then raise exception 'A definition with this name already exists.' using errcode='P0001'; end if;
 if p_kind='belt' then
  if p_action='create' then insert into coderdojo.belts(id,deleted,color,description,hex_code,sort_order) values(p_id,false,name_value,description_value,hex_value,sort_value);
  else update coderdojo.belts set color=name_value,description=description_value,hex_code=hex_value,sort_order=sort_value where id=p_id; end if;
 elsif p_kind='badge' then
  if p_action='create' then insert into coderdojo.badges(id,deleted,achievement,description,badge_category_id) values(p_id,false,name_value,description_value,category_value);
  else update coderdojo.badges set achievement=name_value,description=description_value,badge_category_id=category_value where id=p_id; end if;
 else
  if p_action='create' then insert into coderdojo.badge_categories(id,deleted,category_name,category_description) values(p_id,false,name_value,description_value);
  else update coderdojo.badge_categories set category_name=name_value,category_description=description_value where id=p_id; end if;
 end if;
 return jsonb_build_object('id',p_id,'kind',p_kind,'deleted',false,'name',name_value,'description',description_value,'hexCode',hex_value,'sortOrder',sort_value,'categoryId',category_value);
end; $function$

CREATE OR REPLACE FUNCTION coderdojo.signup_member(p_actor uuid, p_id uuid, p_fields jsonb, p_attendance_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare created_member jsonb;
begin
  created_member := coderdojo.maintain_member(p_actor, 'create', p_id, p_fields - 'attendance_date', '{}'::jsonb);
  if p_attendance_date is not null then
    if p_attendance_date < date '1900-01-01' or p_attendance_date > current_date then
      raise exception 'Invalid signup attendance date' using errcode = '22023';
    end if;
    insert into coderdojo.member_attendances(member_id, date) values (p_id, p_attendance_date);
  end if;
  return created_member;
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.maintain_team(p_actor uuid, p_action text, p_id uuid, p_fields jsonb DEFAULT '{}'::jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 current_team coderdojo.teams%rowtype;
 next_team coderdojo.teams%rowtype;
begin
 perform pg_advisory_xact_lock(731101);
 perform 1 from coderdojo.members where id=p_actor and not deleted and is_mentor for share;
 if not found then raise exception 'Mentor access required' using errcode='42501'; end if;
 if p_action not in ('create','update','delete') then raise exception 'Invalid team action' using errcode='22023'; end if;
 if p_action <> 'create' then
  select * into current_team from coderdojo.teams where id=p_id and not deleted for update;
  if not found then raise exception 'Team not found' using errcode='P0002'; end if;
  if p_expected is null or p_expected = '{}'::jsonb or not (to_jsonb(current_team) @> p_expected) then raise exception 'Team changed elsewhere. Reload before saving.' using errcode='P0001'; end if;
 end if;
 if p_action='delete' then
  if exists(select 1 from coderdojo.members where team_id=p_id and not deleted) then raise exception 'Reassign members before deleting this team.' using errcode='P0001'; end if;
  update coderdojo.teams set deleted=true where id=p_id returning * into next_team;
 else
  if p_fields is null or (p_fields - array['team_name','goal','notes','hexcode']) <> '{}'::jsonb then raise exception 'Invalid team fields' using errcode='22023'; end if;
  next_team := jsonb_populate_record(null::coderdojo.teams,p_fields);
  if next_team.team_name is null or length(btrim(next_team.team_name)) not between 1 and 100 or length(coalesce(next_team.goal,''))>2000 or length(coalesce(next_team.notes,''))>4000 or (next_team.hexcode is not null and next_team.hexcode !~ '^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$') then raise exception 'Invalid team fields' using errcode='22023'; end if;
  if exists(select 1 from coderdojo.teams where not deleted and id<>p_id and lower(btrim(team_name))=lower(btrim(next_team.team_name))) then raise exception 'A team with this name already exists.' using errcode='P0001'; end if;
  if p_action='create' then
   insert into coderdojo.teams(id,deleted,team_name,goal,notes,hexcode) values(p_id,false,btrim(next_team.team_name),next_team.goal,next_team.notes,next_team.hexcode) returning * into next_team;
  else
   update coderdojo.teams set team_name=btrim(next_team.team_name),goal=next_team.goal,notes=next_team.notes,hexcode=next_team.hexcode where id=p_id returning * into next_team;
  end if;
 end if;
 return to_jsonb(next_team);
end; $function$

CREATE OR REPLACE FUNCTION coderdojo.save_profile(p_actor uuid, p_id uuid, p_fields jsonb, p_expected jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 actor_member coderdojo.members%rowtype;
 current_member coderdojo.members%rowtype;
 updated_member coderdojo.members%rowtype;
 allowed_keys text[] := array['login','name_first','name_last','email','phone','github_login','scratch_name','xbox_gamertag'];
begin
 perform pg_advisory_xact_lock(731101);
 select * into actor_member from coderdojo.members where id=p_actor and not deleted for share;
 if not found or (p_actor <> p_id and not actor_member.is_mentor) then
  raise exception 'Profile access denied' using errcode='42501';
 end if;
 if jsonb_typeof(p_fields) <> 'object' or jsonb_typeof(p_expected) <> 'object' or
    not (p_fields ?& allowed_keys) or not (p_expected ?& allowed_keys) or
    (p_fields - allowed_keys) <> '{}'::jsonb or (p_expected - allowed_keys) <> '{}'::jsonb then
  raise exception 'Invalid profile fields' using errcode='22023';
 end if;
 select * into current_member from coderdojo.members where id=p_id and not deleted for update;
 if not found then raise exception 'Profile not found' using errcode='P0002'; end if;
 if not (to_jsonb(current_member) @> p_expected) then
  raise exception 'Profile changed; reload before saving' using errcode='P0001';
 end if;
 updated_member := jsonb_populate_record(current_member,p_fields);
 updated_member.login := trim(updated_member.login);
 if updated_member.login is null or length(updated_member.login) < 1 or length(updated_member.login) > 100 then
  raise exception 'Enter a login of at most 100 characters' using errcode='22023';
 end if;
 -- Existing duplicate identities remain untouched until their owners choose a new login.
 if updated_member.login is distinct from current_member.login and exists (
  select 1 from coderdojo.members where not deleted and id <> p_id and lower(trim(login))=lower(updated_member.login)
 ) then raise exception 'Login already used; choose another login' using errcode='23505'; end if;
 update coderdojo.members set login=updated_member.login,name_first=updated_member.name_first,name_last=updated_member.name_last,
  email=updated_member.email,phone=updated_member.phone,github_login=updated_member.github_login,
  scratch_name=updated_member.scratch_name,xbox_gamertag=updated_member.xbox_gamertag
 where id=p_id returning * into updated_member;
 return to_jsonb(updated_member) - 'password_hash';
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.coder_action(p_actor uuid, p_action text, p_kind text DEFAULT NULL::text, p_definition uuid DEFAULT NULL::uuid, p_fields jsonb DEFAULT '{}'::jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 member_value coderdojo.members%rowtype;
 current_goal timestamp without time zone;
 expected_goal timestamp without time zone;
 record_id uuid;
 next_belt uuid;
 selected boolean;
 notes text;
begin
 -- Definition/merge maintenance uses this same lock before member row locks.
 perform pg_advisory_xact_lock(731101);
 select * into member_value from coderdojo.members where id=p_actor and not deleted and is_ninja for update;
 if not found then raise exception 'Coder access required' using errcode='42501'; end if;
 if p_action='goals' then
  if p_fields is null or p_expected is null or (p_fields-array['goalShortTerm','goalLongTerm'])<>'{}'::jsonb or (p_expected-array['goalShortTerm','goalLongTerm'])<>'{}'::jsonb or not(p_fields?'goalShortTerm' and p_fields?'goalLongTerm' and p_expected?'goalShortTerm' and p_expected?'goalLongTerm') then raise exception 'Invalid goals' using errcode='22023'; end if;
  if length(coalesce(p_fields->>'goalShortTerm',''))>4000 or length(coalesce(p_fields->>'goalLongTerm',''))>4000 then raise exception 'Goals too long' using errcode='22023'; end if;
  if jsonb_build_object('goalShortTerm',member_value.goal_short_term,'goalLongTerm',member_value.goal_long_term) is distinct from p_expected then raise exception 'Goals changed. Reload before saving.' using errcode='P0001'; end if;
  update coderdojo.members set goal_short_term=nullif(btrim(p_fields->>'goalShortTerm'),''),goal_long_term=nullif(btrim(p_fields->>'goalLongTerm'),'') where id=p_actor;
  return null;
 end if;
 if p_action not in ('goal','apply') or p_kind not in ('badge','belt') or p_definition is null then raise exception 'Invalid coder action' using errcode='22023'; end if;
 if p_kind='badge' then
  perform 1 from coderdojo.badges b join coderdojo.badge_categories c on c.id=b.badge_category_id where b.id=p_definition and not b.deleted and not c.deleted for share of b,c;
 else
  perform 1 from coderdojo.belts where id=p_definition and not deleted for share;
 end if;
 if not found then raise exception 'Active achievement required' using errcode='P0002'; end if;
 if (p_kind='badge' and exists(select 1 from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and awarded is not null)) or (p_kind='belt' and exists(select 1 from coderdojo.member_belts where member_id=p_actor and belt_id=p_definition and awarded is not null)) then raise exception 'Achievement already earned' using errcode='P0001'; end if;
 if p_action='goal' then
  if p_kind<>'badge' or p_fields is null or p_expected is null or (p_fields-array['selected'])<>'{}'::jsonb or (p_expected-array['goalDate'])<>'{}'::jsonb or jsonb_typeof(p_fields->'selected') is distinct from 'boolean' or not(p_expected?'goalDate') then raise exception 'Invalid badge goal' using errcode='22023'; end if;
  selected:=(p_fields->>'selected')::boolean;
  select max(goal_date) into current_goal from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and awarded is null;
  expected_goal:=(p_expected->>'goalDate')::timestamp;
  if date_trunc('milliseconds',current_goal) is distinct from expected_goal then raise exception 'Goal changed. Reload before saving.' using errcode='P0001'; end if;
  if not selected then
   update coderdojo.member_badges set goal_date=null where member_id=p_actor and badge_id=p_definition and awarded is null;
  elsif current_goal is null then
   select id into record_id from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and awarded is null and rejected_date is null order by application_date desc nulls last,id limit 1 for update;
   if record_id is null then insert into coderdojo.member_badges(member_id,badge_id,goal_date) values(p_actor,p_definition,date_trunc('milliseconds',timezone('UTC',now())));
   else update coderdojo.member_badges set goal_date=date_trunc('milliseconds',timezone('UTC',now())) where id=record_id; end if;
  end if;
  return null;
 end if;
 if p_fields is null or (p_fields-array['notes'])<>'{}'::jsonb then raise exception 'Invalid application fields' using errcode='22023'; end if;
 notes:=btrim(p_fields->>'notes');
 if notes is null or length(notes) not between 5 and 4000 then raise exception 'Application evidence requires 5 to 4000 characters' using errcode='22023'; end if;
 if p_kind='belt' then
  select id into next_belt from coderdojo.belts b where not b.deleted and not exists(select 1 from coderdojo.member_belts mb where mb.member_id=p_actor and mb.belt_id=b.id and mb.awarded is not null) order by b.sort_order,b.color,b.id limit 1;
  if next_belt is distinct from p_definition then raise exception 'Apply only for your next belt' using errcode='P0001'; end if;
  select id into record_id from coderdojo.member_belts where member_id=p_actor and belt_id=p_definition and application_date is not null and awarded is null and rejected_date is null order by id limit 1 for update;
  if record_id is null then insert into coderdojo.member_belts(member_id,belt_id,application_date,application_notes) values(p_actor,p_definition,date_trunc('milliseconds',timezone('UTC',now())),notes) returning id into record_id; end if;
 else
  select id into record_id from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and application_date is not null and awarded is null and rejected_date is null order by id limit 1 for update;
  if record_id is null then
   select id into record_id from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and application_date is null and awarded is null and rejected_date is null order by goal_date desc nulls last,id limit 1 for update;
   if record_id is null then
    select max(goal_date) into current_goal from coderdojo.member_badges where member_id=p_actor and badge_id=p_definition and awarded is null;
    insert into coderdojo.member_badges(member_id,badge_id,goal_date,application_date,application_notes) values(p_actor,p_definition,current_goal,date_trunc('milliseconds',timezone('UTC',now())),notes) returning id into record_id;
   else update coderdojo.member_badges set application_date=date_trunc('milliseconds',timezone('UTC',now())),application_notes=notes where id=record_id; end if;
  end if;
 end if;
 return jsonb_build_object('id',record_id);
end; $function$

CREATE OR REPLACE FUNCTION coderdojo.merge_members(p_actor uuid, p_keep uuid, p_duplicate uuid, p_fields jsonb, p_expected_keep jsonb, p_expected_duplicate jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 keep_member coderdojo.members%rowtype;
 duplicate_member coderdojo.members%rowtype;
 selected coderdojo.members%rowtype;
begin
 if p_keep = p_duplicate or p_actor in (p_keep, p_duplicate) then raise exception 'Cannot merge this account' using errcode='22023'; end if;
 perform 1 from coderdojo.members where id in (p_actor,p_keep,p_duplicate) order by id for update;
 if not exists(select 1 from coderdojo.members where id=p_actor and is_mentor and not deleted) then raise exception 'Mentor access required' using errcode='42501'; end if;
 select * into keep_member from coderdojo.members where id=p_keep and not deleted;
 if not found then raise exception 'Survivor unavailable' using errcode='P0002'; end if;
 select * into duplicate_member from coderdojo.members where id=p_duplicate and not deleted;
 if not found then raise exception 'Duplicate unavailable' using errcode='P0001'; end if;
 if keep_member.is_ninja <> duplicate_member.is_ninja then raise exception 'Choose compatible accounts' using errcode='22023'; end if;
 if exists(select 1 from coderdojo.member_parents where (member_id=p_keep and parent_id=p_duplicate) or (member_id=p_duplicate and parent_id=p_keep)) then raise exception 'Linked accounts cannot be merged' using errcode='22023'; end if;
 if (to_jsonb(keep_member)-array['password_hash','login_date','login_date_previous']) is distinct from p_expected_keep or (to_jsonb(duplicate_member)-array['password_hash','login_date','login_date_previous']) is distinct from p_expected_duplicate then raise exception 'Accounts changed; review again' using errcode='P0001'; end if;
 if p_fields is null or exists(select 1 from jsonb_object_keys(p_fields) k where k not in ('birth_year','email','phone','github_login','scratch_name','xbox_gamertag','team_id','goal_short_term','goal_long_term')) then raise exception 'Invalid merge fields' using errcode='22023'; end if;
 selected := jsonb_populate_record(keep_member,p_fields);
 if selected.team_id is not null and not exists(select 1 from coderdojo.teams where id=selected.team_id and not deleted) then raise exception 'Team unavailable' using errcode='P0001'; end if;
 update coderdojo.members set birth_year=selected.birth_year,email=selected.email,phone=selected.phone,github_login=selected.github_login,scratch_name=selected.scratch_name,xbox_gamertag=selected.xbox_gamertag,team_id=selected.team_id,goal_short_term=selected.goal_short_term,goal_long_term=selected.goal_long_term,
 is_parent=keep_member.is_parent or duplicate_member.is_parent,is_mentor=keep_member.is_mentor or duplicate_member.is_mentor,garda_vetted=keep_member.garda_vetted or duplicate_member.garda_vetted,registered_current_term=keep_member.registered_current_term or duplicate_member.registered_current_term
 where id=p_keep;
 -- Redundant source rows remain on the archived account; no history is permanently discarded.
 update coderdojo.member_attendances s set member_id=p_keep where s.member_id=p_duplicate and not exists(select 1 from coderdojo.member_attendances k where k.member_id=p_keep and k.date=s.date);
 update coderdojo.member_parents s set member_id=p_keep where s.member_id=p_duplicate and not exists(select 1 from coderdojo.member_parents k where k.member_id=p_keep and k.parent_id=s.parent_id);
 update coderdojo.member_parents s set parent_id=p_keep where s.parent_id=p_duplicate and not exists(select 1 from coderdojo.member_parents k where k.parent_id=p_keep and k.member_id=s.member_id);
 update coderdojo.member_badge_categories s set member_id=p_keep where s.member_id=p_duplicate and not exists(select 1 from coderdojo.member_badge_categories k where k.member_id=p_keep and k.badge_category_id=s.badge_category_id);
 update coderdojo.member_badges s set member_id=p_keep where s.member_id=p_duplicate and (s.awarded is null or not exists(select 1 from coderdojo.member_badges k where k.member_id=p_keep and k.badge_id=s.badge_id and k.awarded is not null));
 update coderdojo.member_belts s set member_id=p_keep where s.member_id=p_duplicate and (s.awarded is null or not exists(select 1 from coderdojo.member_belts k where k.member_id=p_keep and k.belt_id=s.belt_id and k.awarded is not null));
 update coderdojo.member_badges set awarded_by_adult_id=p_keep where awarded_by_adult_id=p_duplicate;
 update coderdojo.member_badges set rejected_by_adult_id=p_keep where rejected_by_adult_id=p_duplicate;
 update coderdojo.member_belts set awarded_by_adult_id=p_keep where awarded_by_adult_id=p_duplicate;
 update coderdojo.member_belts set rejected_by_adult_id=p_keep where rejected_by_adult_id=p_duplicate;
 update coderdojo.members set deleted=true where id=p_duplicate;
 select * into keep_member from coderdojo.members where id=p_keep;
 return to_jsonb(keep_member)-'password_hash';
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.decide_achievement(p_actor uuid, p_kind text, p_id uuid, p_action text, p_notes text, p_expected_awarded timestamp with time zone, p_expected_rejected timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 applicant uuid;
 current_application timestamp;
 current_awarded timestamp;
 current_rejected timestamp;
 now_value timestamp := date_trunc('milliseconds', current_timestamp at time zone 'UTC');
begin
 if p_kind not in ('badge','belt') or p_action not in ('approve','reject','undo') or length(coalesce(p_notes,''))>4000 or (p_action<>'undo' and nullif(trim(p_notes),'') is null) then raise exception 'Invalid decision' using errcode='22023'; end if;
 if p_kind='badge' then select member_id into applicant from coderdojo.member_badges where id=p_id; else select member_id into applicant from coderdojo.member_belts where id=p_id; end if;
 if applicant is null then raise exception 'Application unavailable' using errcode='P0002'; end if;
 -- Relationships and account merges lock these members too, preventing a link/merge race.
 perform 1 from coderdojo.members where id in (p_actor,applicant) order by id for update;
 if not exists(select 1 from coderdojo.members where id=p_actor and is_mentor and not deleted) then raise exception 'Mentor access required' using errcode='42501'; end if;
 if not exists(select 1 from coderdojo.members where id=applicant and not deleted) then raise exception 'Applicant unavailable' using errcode='P0002'; end if;
 if p_action <> 'undo' and exists(select 1 from coderdojo.member_parents where parent_id=p_actor and member_id=applicant) then raise exception 'Another mentor must review your child' using errcode='42501'; end if;
 if p_kind='badge' then
  select application_date,awarded,rejected_date into current_application,current_awarded,current_rejected from coderdojo.member_badges where id=p_id and member_id=applicant for update;
 else
  select application_date,awarded,rejected_date into current_application,current_awarded,current_rejected from coderdojo.member_belts where id=p_id and member_id=applicant for update;
 end if;
 if not found or current_application is null or date_trunc('milliseconds',current_awarded) is distinct from (p_expected_awarded at time zone 'UTC') or date_trunc('milliseconds',current_rejected) is distinct from (p_expected_rejected at time zone 'UTC') or (p_action='undo' and current_awarded is null and current_rejected is null) or (p_action<>'undo' and (current_awarded is not null or current_rejected is not null)) then raise exception 'Application changed; review again' using errcode='P0001'; end if;
 if p_kind='badge' then
  update coderdojo.member_badges set awarded=case when p_action='approve' then now_value end,awarded_by_adult_id=case when p_action='approve' then p_actor end,awarded_notes=case when p_action='approve' then trim(p_notes) end,rejected_date=case when p_action='reject' then now_value end,rejected_by_adult_id=case when p_action='reject' then p_actor end,rejected_notes=case when p_action='reject' then trim(p_notes) end where id=p_id;
 else
  update coderdojo.member_belts set awarded=case when p_action='approve' then now_value end,awarded_by_adult_id=case when p_action='approve' then p_actor end,awarded_notes=case when p_action='approve' then trim(p_notes) end,rejected_date=case when p_action='reject' then now_value end,rejected_by_adult_id=case when p_action='reject' then p_actor end,rejected_notes=case when p_action='reject' then trim(p_notes) end where id=p_id;
 end if;
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.join_coder_session(p_actor uuid, p_session uuid, p_expected_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform 1 from coderdojo.members where id=p_actor and not deleted and is_ninja;
 if not found then raise exception 'Coder access required' using errcode='42501'; end if;
 return coderdojo.join_member_session(p_actor,p_session,p_expected_url);
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.maintain_session_pod(p_actor uuid, p_action text, p_id uuid DEFAULT NULL::uuid, p_fields jsonb DEFAULT '{}'::jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 current_value coderdojo.session_pods%rowtype;
 current_snapshot jsonb;
 result_id uuid;
 topic_value text;
 url_value text;
 host_value uuid;
 host2_value uuid;
 now_value timestamptz := date_trunc('milliseconds',now());
begin
 perform pg_advisory_xact_lock(731101);
 perform 1 from coderdojo.members where id=p_actor and is_mentor and not deleted for update;
 if not found then raise exception 'Mentor access required' using errcode='42501'; end if;
 if p_action not in ('create','update','delete') then raise exception 'Invalid pod action' using errcode='22023'; end if;
 if p_action<>'create' then
  select * into current_value from coderdojo.session_pods where id=p_id and not deleted for update;
  if not found then raise exception 'Session unavailable' using errcode='P0002'; end if;
  current_snapshot:=jsonb_build_object('topic',current_value.topic,'url',current_value.url,'hostId',current_value.host_id,'host2Id',current_value.host2_id,'mentorsOnly',current_value.mentors_only,'sessionDate',current_value.session_date::text,'endsAt',case when current_value.ends_at is null then null else floor(extract(epoch from current_value.ends_at)*1000)::bigint end);
  if current_snapshot is distinct from p_expected then raise exception 'Session changed. Reload before saving.' using errcode='P0001'; end if;
  if p_action='delete' then update coderdojo.session_pods set deleted=true where id=p_id; return jsonb_build_object('id',p_id); end if;
 end if;
 if p_fields is null or (p_fields-array['topic','url','hostId','host2Id','mentorsOnly'])<>'{}'::jsonb or not(p_fields?'topic' and p_fields?'url' and p_fields?'hostId' and p_fields?'host2Id' and p_fields?'mentorsOnly') or jsonb_typeof(p_fields->'mentorsOnly')<>'boolean' then raise exception 'Invalid pod fields' using errcode='22023'; end if;
 topic_value:=nullif(btrim(p_fields->>'topic'),'');url_value:=nullif(btrim(p_fields->>'url'),'');
 if topic_value is null or length(topic_value)>200 or length(coalesce(url_value,''))>2000 or (url_value is not null and url_value!~'^https?://[^/?#[:space:]@]+') then raise exception 'Invalid topic or URL' using errcode='22023'; end if;
 begin host_value:=(p_fields->>'hostId')::uuid;host2_value:=(p_fields->>'host2Id')::uuid;exception when invalid_text_representation then raise exception 'Invalid host' using errcode='22023';end;
 if host_value is null or host_value=host2_value then raise exception 'Choose distinct active mentor hosts' using errcode='22023'; end if;
 perform 1 from coderdojo.members where id=host_value and is_mentor and not deleted for share;
 if not found then raise exception 'Primary host is unavailable' using errcode='P0001'; end if;
 if host2_value is not null then
  perform 1 from coderdojo.members where id=host2_value and is_mentor and not deleted for share;
  if not found then raise exception 'Second host is unavailable' using errcode='P0001'; end if;
 end if;
 if p_action='create' then
  insert into coderdojo.session_pods(topic,url,host_id,host2_id,mentors_only,session_date,ends_at)
   values(topic_value,url_value,host_value,host2_value,(p_fields->>'mentorsOnly')::boolean,(now_value at time zone 'Europe/Dublin')::date,now_value+interval '150 minutes') returning id into result_id;
 else
  update coderdojo.session_pods set topic=topic_value,url=url_value,host_id=host_value,host2_id=host2_value,mentors_only=(p_fields->>'mentorsOnly')::boolean,session_date=(now_value at time zone 'Europe/Dublin')::date,ends_at=now_value+interval '150 minutes' where id=p_id returning id into result_id;
 end if;
 return jsonb_build_object('id',result_id);
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.join_member_session(p_actor uuid, p_session uuid, p_expected_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 member_value coderdojo.members%rowtype;
 session_value coderdojo.session_pods%rowtype;
 today date := (now() at time zone 'Europe/Dublin')::date;
begin
 perform pg_advisory_xact_lock(731101);
 select * into member_value from coderdojo.members where id=p_actor and not deleted and (is_ninja or is_mentor or is_parent) for update;
 if not found then raise exception 'Member access required' using errcode='42501'; end if;
 select * into session_value from coderdojo.session_pods where id=p_session and not deleted for share;
 if not found or (session_value.mentors_only and not member_value.is_mentor) then raise exception 'Session unavailable' using errcode='P0002'; end if;
 if (session_value.ends_at is not null and session_value.ends_at<=now()) or (session_value.ends_at is null and session_value.session_date<today) then raise exception 'Session has ended' using errcode='P0001'; end if;
 if session_value.url is null or session_value.url!~'^https?://[^/?#[:space:]@]+' then raise exception 'Session has no valid joining URL' using errcode='22023'; end if;
 if session_value.url is distinct from p_expected_url then raise exception 'Session URL changed. Refresh before joining.' using errcode='P0001'; end if;
 insert into coderdojo.member_attendances(member_id,date) values(p_actor,today) on conflict(member_id,date) do nothing;
 return jsonb_build_object('url',session_value.url,'attendanceDate',today::text);
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.maintain_data(p_actor uuid, p_action text, p_apply boolean DEFAULT false, p_expected text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 cutoff date := ((now() at time zone 'Europe/Dublin')::date - interval '1 year')::date;
 coder_ids uuid[] := '{}';
 parent_ids uuid[] := '{}';
 registration_ids uuid[] := '{}';
 candidates jsonb;
 revision text;
 result jsonb;
begin
 if p_action is null or p_action not in ('members', 'registrations') or p_apply is null
  or (p_apply and (p_expected is null or p_expected !~ '^[0-9a-f]{32}$'))
  or (not p_apply and p_expected is not null) then
  raise exception 'Invalid maintenance action' using errcode = '22023';
 end if;
 -- Match the shared mutation lock order; prevent attendance/link/role edits during apply.
 perform pg_advisory_xact_lock(731101);
 if p_apply then
  lock table coderdojo.members, coderdojo.member_attendances, coderdojo.member_parents in share row exclusive mode;
 end if;
 perform 1 from coderdojo.members where id = p_actor and is_mentor and not deleted for share;
 if not found then raise exception 'Mentor access required' using errcode = '42501'; end if;

 if p_action = 'members' then
  select coalesce(array_agg(m.id order by m.id), '{}') into coder_ids
  from coderdojo.members m
  where not m.deleted and m.is_ninja and not m.is_mentor
   and coalesce((select max(a.date) from coderdojo.member_attendances a where a.member_id = m.id), date '2000-01-01') < cutoff;
  -- In the unified table, never archive an active coder or mentor via their parent role.
  select coalesce(array_agg(p.id order by p.id), '{}') into parent_ids
  from coderdojo.members p
  where not p.deleted and p.is_parent and not p.is_mentor
   and (not p.is_ninja or p.id = any(coder_ids))
   and not exists(select 1 from coderdojo.member_parents r join coderdojo.members c on c.id = r.member_id
    where r.parent_id = p.id and not c.deleted and not(c.id = any(coder_ids)));
  -- A multi-role coder/parent is counted once, as a coder.
  parent_ids := array(select unnest(parent_ids) except select unnest(coder_ids));
 else
  -- Legacy purge includes archived coders, but excludes adult-only accounts.
  select coalesce(array_agg(m.id order by m.id), '{}') into registration_ids
  from coderdojo.members m where m.is_ninja and m.registered_current_term;
 end if;

 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'name',concat_ws(' ',m.name_first,m.name_last),
  'kind',case when m.id = any(coder_ids) then 'coder' when m.id = any(parent_ids) then 'parent' else 'registration' end,
  'lastAttendance',(select max(a.date)::text from coderdojo.member_attendances a where a.member_id=m.id),
  'archived',m.deleted) order by m.name_first,m.name_last,m.id),'[]'::jsonb) into candidates
 from coderdojo.members m where m.id = any(coder_ids || parent_ids || registration_ids);
 revision := md5(jsonb_build_object('action',p_action,'cutoff',cutoff,'candidates',candidates)::text);
 if p_apply and revision is distinct from p_expected then
  raise exception 'Maintenance preview changed. Refresh and review again.' using errcode = 'P0001';
 end if;
 result := jsonb_build_object('action',p_action,'cutoff',cutoff::text,'revision',revision,'candidates',candidates,
  'coders',cardinality(coder_ids),'parents',cardinality(parent_ids),'registrations',cardinality(registration_ids),'applied',p_apply);
 if p_apply then
  if p_action = 'members' then
   update coderdojo.members set deleted = true where id = any(coder_ids || parent_ids);
  else
   update coderdojo.members set registered_current_term = false where id = any(registration_ids);
  end if;
 end if;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION coderdojo.maintain_parent_child(p_actor uuid, p_id uuid, p_action text, p_fields jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 actor_member coderdojo.members%rowtype;
 current_member coderdojo.members%rowtype;
 updated_member coderdojo.members%rowtype;
 allowed_keys text[];
begin
 perform pg_advisory_xact_lock(731101);
 select * into actor_member from coderdojo.members where id=p_actor and not deleted for share;
 if not found or not actor_member.is_parent then raise exception 'Parent access required' using errcode='42501'; end if;
 perform 1 from coderdojo.member_parents where parent_id=p_actor and member_id=p_id for share;
 if not found then raise exception 'Child unavailable' using errcode='42501'; end if;
 select * into current_member from coderdojo.members where id=p_id and not deleted and is_ninja for update;
 if not found then raise exception 'Child unavailable' using errcode='P0002'; end if;
 if p_action='save' then allowed_keys:=array['birth_year','login','github_login','scratch_name','xbox_gamertag'];
 elsif p_action='password' then allowed_keys:=array['password_hash'];
 elsif p_action='images' then allowed_keys:=array['has_photo','has_avatar'];
 else raise exception 'Invalid child action' using errcode='22023'; end if;
 if jsonb_typeof(p_fields) is distinct from 'object' or not(p_fields ?& allowed_keys) or (p_fields-allowed_keys)<>'{}'::jsonb then raise exception 'Invalid child fields' using errcode='22023'; end if;
 if p_action<>'password' then
  if jsonb_typeof(p_expected) is distinct from 'object' or not(p_expected ?& allowed_keys) or (p_expected-allowed_keys)<>'{}'::jsonb then raise exception 'Invalid child snapshot' using errcode='22023'; end if;
  if not(to_jsonb(current_member) @> p_expected) then raise exception 'Child changed; reload before saving' using errcode='P0001'; end if;
 elsif p_expected<>'{}'::jsonb then raise exception 'Invalid password snapshot' using errcode='22023'; end if;
 updated_member:=jsonb_populate_record(current_member,p_fields);
 if p_action='save' then
  updated_member.login:=trim(updated_member.login);
  if updated_member.login is null or length(updated_member.login)<1 or length(updated_member.login)>100 or
   (updated_member.birth_year is not null and (updated_member.birth_year<1900 or updated_member.birth_year>extract(year from current_date))) or
   length(coalesce(updated_member.github_login,''))>100 or length(coalesce(updated_member.scratch_name,''))>100 or length(coalesce(updated_member.xbox_gamertag,''))>100 then raise exception 'Invalid child account fields' using errcode='22023'; end if;
  if updated_member.login is distinct from current_member.login and exists(select 1 from coderdojo.members where not deleted and id<>p_id and lower(trim(login))=lower(updated_member.login)) then raise exception 'Login already used; choose another login' using errcode='23505'; end if;
  update coderdojo.members set birth_year=updated_member.birth_year,login=updated_member.login,github_login=updated_member.github_login,scratch_name=updated_member.scratch_name,xbox_gamertag=updated_member.xbox_gamertag where id=p_id returning * into updated_member;
 elsif p_action='password' then
  if updated_member.password_hash is null or updated_member.password_hash!~'^[0-9a-f]{64}$' then raise exception 'Invalid password hash' using errcode='22023'; end if;
  update coderdojo.members set password_hash=updated_member.password_hash where id=p_id returning * into updated_member;
 else
  if jsonb_typeof(p_fields->'has_photo')<>'boolean' or jsonb_typeof(p_fields->'has_avatar')<>'boolean' then raise exception 'Invalid image flags' using errcode='22023'; end if;
  update coderdojo.members set has_photo=updated_member.has_photo,has_avatar=updated_member.has_avatar where id=p_id returning * into updated_member;
 end if;
 return to_jsonb(updated_member)-'password_hash';
end;
$function$
